export type ParsedCloseIntentInstruction<
  TProgram extends string = typeof INTENT_ENGINE_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    cranker: TAccountMetas[0];
    intent: TAccountMetas[1];
    vault: TAccountMetas[2];
    inputMint: TAccountMetas[3];
    refundTo: TAccountMetas[4];
    canonicalRefund: TAccountMetas[5];
    owner: TAccountMetas[6];
    rentPayer: TAccountMetas[7];
    tokenProgram: TAccountMetas[8];
    mintCap?: TAccountMetas[9] | undefined;
    eventAuthority: TAccountMetas[10];
    program: TAccountMetas[11];
  };
  data: CloseIntentInstructionData;
};

export function parseCloseIntentInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedCloseIntentInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 12) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 12,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === INTENT_ENGINE_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      cranker: getNextAccount(),
      intent: getNextAccount(),
      vault: getNextAccount(),
      inputMint: getNextAccount(),
      refundTo: getNextAccount(),
      canonicalRefund: getNextAccount(),
      owner: getNextAccount(),
      rentPayer: getNextAccount(),
      tokenProgram: getNextAccount(),
      mintCap: getNextOptionalAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getCloseIntentInstructionDataDecoder().decode(instruction.data),
  };
}
